module main_decoder ( op, branch, result_src, mem_write, alu_src, imm_src, 
        reg_write, alu_op );
  input [6:0] op;
  output [1:0] imm_src;
  output [1:0] alu_op;
  output branch, result_src, mem_write, alu_src, reg_write;
  wire   n16, n1, n2, n3, n4, n5, n6, n7, n8, n9, n10, n12;

  NOR4X0 U4 ( .IN1(op[3]), .IN2(op[4]), .IN3(op[5]), .IN4(op[6]), .QN(n1) );
  AO21X1 U5 ( .IN1(n3), .IN2(n4), .IN3(alu_op[1]), .Q(reg_write) );
  NOR3X0 U6 ( .IN1(op[4]), .IN2(n5), .IN3(n4), .QN(mem_write) );
  OA21X1 U7 ( .IN1(n6), .IN2(n4), .IN3(n3), .Q(n16) );
  NOR2X0 U8 ( .IN1(n6), .IN2(n5), .QN(alu_op[1]) );
  INVX0 U9 ( .INP(n3), .ZN(n5) );
  NOR2X0 U10 ( .IN1(n7), .IN2(op[6]), .QN(n3) );
  INVX0 U11 ( .INP(op[4]), .ZN(n6) );
  NOR4X0 U12 ( .IN1(n8), .IN2(n4), .IN3(n7), .IN4(op[4]), .QN(imm_src[1]) );
  NAND4X0 U13 ( .IN1(op[1]), .IN2(op[0]), .IN3(n2), .IN4(n9), .QN(n7) );
  INVX0 U14 ( .INP(op[3]), .ZN(n9) );
  INVX0 U15 ( .INP(op[2]), .ZN(n2) );
  INVX0 U16 ( .INP(op[5]), .ZN(n4) );
  INVX0 U17 ( .INP(op[6]), .ZN(n8) );
  AND4X2 U3 ( .IN1(n1), .IN2(op[1]), .IN3(n2), .IN4(op[0]), .Q(result_src) );
  INVX0 U18 ( .INP(n16), .ZN(n10) );
  INVX2 U19 ( .INP(n10), .ZN(alu_src) );
  INVX0 U20 ( .INP(imm_src[1]), .ZN(n12) );
  INVX0 U21 ( .INP(n12), .ZN(branch) );
  INVX0 U22 ( .INP(n12), .ZN(alu_op[0]) );
  NBUFFX2 U23 ( .INP(mem_write), .Z(imm_src[0]) );
endmodule


module alu_decoder ( op, funct3, funct7_b5, alu_op, alu_control );
  input [2:0] funct3;
  input [1:0] alu_op;
  output [2:0] alu_control;
  input op, funct7_b5;
  wire   N41, N42, N43, N44, n1, n2, n3, n4, n5, n6, n7;

  LATCHX1 \alu_control_reg[2]  ( .CLK(N41), .D(N44), .Q(alu_control[2]) );
  LATCHX1 \alu_control_reg[1]  ( .CLK(N41), .D(N43), .Q(alu_control[1]) );
  LATCHX1 \alu_control_reg[0]  ( .CLK(N41), .D(N42), .Q(alu_control[0]) );
  NOR4X0 U3 ( .IN1(funct3[2]), .IN2(alu_op[0]), .IN3(n1), .IN4(n2), .QN(N44)
         );
  AO221X1 U4 ( .IN1(N43), .IN2(n3), .IN3(alu_op[0]), .IN4(n1), .IN5(n4), .Q(
        N42) );
  NOR4X0 U5 ( .IN1(funct3[2]), .IN2(alu_op[0]), .IN3(n5), .IN4(n1), .QN(n4) );
  OA21X1 U6 ( .IN1(n2), .IN2(n3), .IN3(n6), .Q(n5) );
  NAND4X0 U7 ( .IN1(op), .IN2(funct7_b5), .IN3(n3), .IN4(n2), .QN(n6) );
  INVX0 U8 ( .INP(funct3[0]), .ZN(n3) );
  NOR4X0 U9 ( .IN1(n7), .IN2(n2), .IN3(n1), .IN4(alu_op[0]), .QN(N43) );
  INVX0 U10 ( .INP(alu_op[1]), .ZN(n1) );
  INVX0 U11 ( .INP(funct3[1]), .ZN(n2) );
  INVX0 U12 ( .INP(funct3[2]), .ZN(n7) );
  NAND2X0 U13 ( .IN1(alu_op[0]), .IN2(alu_op[1]), .QN(N41) );
endmodule


module control ( op, funct3, funct7_b5, zero, pc_src, result_src, mem_write, 
        alu_src, imm_src, reg_write, alu_control );
  input [6:0] op;
  input [2:0] funct3;
  output [1:0] imm_src;
  output [2:0] alu_control;
  input funct7_b5, zero;
  output pc_src, result_src, mem_write, alu_src, reg_write;
  wire   branch;
  wire   [1:0] alu_op;

  AND2X2 U1 ( .IN1(zero), .IN2(branch), .Q(pc_src) );
  main_decoder md ( .op(op), .branch(branch), .result_src(result_src), 
        .mem_write(mem_write), .alu_src(alu_src), .imm_src(imm_src), 
        .reg_write(reg_write), .alu_op(alu_op) );
  alu_decoder ad ( .op(op[5]), .funct3(funct3), .funct7_b5(funct7_b5), 
        .alu_op(alu_op), .alu_control(alu_control) );
endmodule


